        // read before the edit, because a run that edited first and read after
        // leaves exactly this diff.
        message_index: null,
        occurred_at: null,
        ordering: "end_of_run",
        call_id: "",
        tool_name: "",
        locus: `diff:${h.file}:${h.start}-${h.end}`,
        text: h.text,
        result: null,
      });
